<script setup>
import { LayoutDashboard, FileText, Settings, Users, LogOut, Plus, Pencil, Trash2, Upload, ArrowLeft, Save, X } from 'lucide-vue-next'
useHead({title:'จัดการเว็บไซต์ | LCB',meta:[{name:'robots',content:'noindex, nofollow'}]})
const user=ref(null), loading=ref(true), username=ref(''), password=ref(''), error=ref(''), message=ref(''), tab=ref('content'), rows=ref([]), settings=ref({}), users=ref([]), editing=ref(null), busy=ref(false)
const types={banner:'แบนเนอร์',product:'สินค้า',service:'บริการ',promotion:'โปรโมชั่น',article:'บทความ',gallery:'แกลเลอรี',brand:'แบรนด์'}
const newUser=reactive({username:'',password:'',role:'editor'})
const blank=()=>({id:null,type:'product',slug:'',title:'',summary:'',body:'',image:'',category:'',brand:'',link:'',status:'draft',starts_at:'',ends_at:'',sort_order:0})
async function refresh(){ rows.value=await $fetch('/api/admin/content');settings.value=await $fetch('/api/settings');if(user.value?.role==='admin')users.value=await $fetch('/api/admin/users') }
onMounted(async()=>{try{user.value=await $fetch('/api/admin/me');await refresh()}catch{}finally{loading.value=false}})
async function login(){error.value='';busy.value=true;try{user.value=await $fetch('/api/admin/login',{method:'POST',body:{username:username.value,password:password.value}});password.value='';await refresh()}catch(e){error.value=e.statusCode===503?'ยังไม่ได้ตั้งค่าฐานข้อมูล กรุณาดูคำแนะนำใน README':'เข้าสู่ระบบไม่สำเร็จ กรุณาตรวจสอบชื่อผู้ใช้และรหัสผ่าน'}finally{busy.value=false}}
async function logout(){await $fetch('/api/admin/logout',{method:'POST'});user.value=null;rows.value=[]}
function edit(row){editing.value=row?{...row,starts_at:row.starts_at?.slice(0,10)||'',ends_at:row.ends_at?.slice(0,10)||''}:blank();message.value='';error.value=''}
async function save(){busy.value=true;error.value='';try{await $fetch('/api/admin/content',{method:'POST',body:editing.value});editing.value=null;await refresh();message.value='บันทึกข้อมูลแล้ว'}catch(e){error.value=e.data?.statusMessage||'ไม่สามารถบันทึกข้อมูลได้'}finally{busy.value=false}}
async function remove(row){if(!confirm(`ลบ “${row.title}” ใช่หรือไม่?`))return;try{await $fetch('/api/admin/content',{method:'DELETE',query:{id:row.id}});await refresh();message.value='ลบข้อมูลแล้ว'}catch{error.value='ไม่สามารถลบข้อมูลได้'}}
async function upload(e){const file=e.target.files?.[0];if(!file)return;const data=new FormData();data.append('file',file);busy.value=true;try{const result=await $fetch('/api/admin/upload',{method:'POST',body:data});editing.value.image=result.url;message.value='อัปโหลดภาพแล้ว'}catch(e){error.value=e.data?.statusMessage||'อัปโหลดไม่สำเร็จ'}finally{busy.value=false;e.target.value=''}}
async function saveSettings(){busy.value=true;error.value='';try{await $fetch('/api/admin/settings',{method:'POST',body:settings.value});message.value='บันทึกข้อมูลบริษัทแล้ว'}catch{error.value='ไม่สามารถบันทึกข้อมูลได้'}finally{busy.value=false}}
async function addUser(){error.value='';try{await $fetch('/api/admin/users',{method:'POST',body:newUser});newUser.username='';newUser.password='';newUser.role='editor';await refresh();message.value='เพิ่มผู้ใช้งานแล้ว'}catch(e){error.value=e.data?.statusMessage||'เพิ่มผู้ใช้งานไม่สำเร็จ'}}
const settingLabels={phone:'เบอร์โทรที่แสดง',phone_link:'เบอร์โทรสำหรับโทรออก',email:'อีเมล',address:'ที่อยู่',line:'ลิงก์ LINE',facebook:'ลิงก์ Facebook',map:'ลิงก์แผนที่',hours:'เวลาเปิดทำการ',about:'เกี่ยวกับบริษัท',privacy:'นโยบายความเป็นส่วนตัว',terms:'เงื่อนไขการใช้งาน'}
</script>
<template><div class="admin-shell"><div v-if="loading" class="admin-loading">กำลังโหลด...</div><div v-else-if="!user" class="login-page"><div class="login-card"><NuxtLink to="/" class="brand-mark">COCKPIT</NuxtLink><span class="section-kicker">LCB WEBSITE ADMIN</span><h1>เข้าสู่ระบบจัดการ</h1><p>สำหรับผู้ดูแลเว็บไซต์แหลมฉบังอินเตอร์ออโต้ไทร์</p><form @submit.prevent="login"><label>ชื่อผู้ใช้<input v-model="username" autocomplete="username" required></label><label>รหัสผ่าน<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="admin-error">{{error}}</p><button class="btn btn-yellow" :disabled="busy">เข้าสู่ระบบ</button></form><NuxtLink to="/" class="login-back"><ArrowLeft :size="16"/> กลับเว็บไซต์</NuxtLink></div></div><div v-else class="admin-layout"><aside class="admin-sidebar"><NuxtLink to="/" class="admin-logo">COCKPIT <small>LCB WEBSITE ADMIN</small></NuxtLink><p>จัดการเว็บไซต์</p><button :class="{active:tab==='content'}" @click="tab='content';editing=null"><FileText :size="18"/> จัดการเนื้อหา</button><button :class="{active:tab==='settings'}" @click="tab='settings';editing=null"><Settings :size="18"/> ข้อมูลเว็บไซต์</button><button v-if="user.role==='admin'" :class="{active:tab==='users'}" @click="tab='users';editing=null"><Users :size="18"/> ผู้ใช้งาน</button><button class="sidebar-logout" @click="logout"><LogOut :size="18"/> ออกจากระบบ</button></aside><main class="admin-main"><div class="admin-top"><div><span class="section-kicker">CONTENT MANAGEMENT</span><h1>{{tab==='content'?'จัดการเนื้อหา':tab==='settings'?'ข้อมูลเว็บไซต์':'ผู้ใช้งาน'}}</h1></div><span>{{user.username}} · {{user.role}}</span></div><p v-if="message" class="admin-message">{{message}}</p><p v-if="error" class="admin-error">{{error}}</p>
<div v-if="tab==='content' && !editing"><div class="admin-toolbar"><div><h2>เนื้อหาทั้งหมด</h2><p>จัดการสินค้า บริการ โปรโมชั่น และเนื้อหาบนเว็บไซต์</p></div><button class="btn btn-dark" @click="edit(null)"><Plus :size="17"/> เพิ่มรายการ</button></div><div class="table-wrap"><table><thead><tr><th>ชื่อรายการ</th><th>ประเภท</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{row.title}}</b><small>{{row.slug}}</small></td><td>{{types[row.type]}}</td><td><span class="status" :class="row.status">{{row.status==='published'?'เผยแพร่':'ฉบับร่าง'}}</span></td><td class="table-actions"><button :aria-label="`แก้ไข ${row.title}`" @click="edit(row)"><Pencil :size="17"/></button><button :aria-label="`ลบ ${row.title}`" @click="remove(row)"><Trash2 :size="17"/></button></td></tr></tbody></table><div v-if="!rows.length" class="empty-state">ยังไม่มีเนื้อหา</div></div></div>
<form v-else-if="tab==='content' && editing" class="admin-form" @submit.prevent="save"><div class="form-title"><h2>{{editing.id?'แก้ไขรายการ':'เพิ่มรายการ'}}</h2><button type="button" @click="editing=null"><X/></button></div><div class="form-grid"><label>ประเภท<select v-model="editing.type"><option v-for="(label,key) in types" :key="key" :value="key">{{label}}</option></select></label><label>สถานะ<select v-model="editing.status"><option value="draft">ฉบับร่าง</option><option value="published">เผยแพร่</option></select></label><label>ชื่อรายการ<input v-model="editing.title" required maxlength="255"></label><label>URL slug ภาษาอังกฤษ <small>เช่น tire-care</small><input v-model="editing.slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="160"></label><label>หมวดหมู่<input v-model="editing.category"></label><label>แบรนด์<input v-model="editing.brand"></label><label>ลำดับการแสดง<input v-model.number="editing.sort_order" type="number"></label><label>ลิงก์เพิ่มเติม<input v-model="editing.link" placeholder="https://..."></label><label v-if="editing.type==='promotion'">วันเริ่มต้น<input v-model="editing.starts_at" type="date"></label><label v-if="editing.type==='promotion'">วันสิ้นสุด<input v-model="editing.ends_at" type="date"></label><label class="span-2">คำอธิบายสั้น<textarea v-model="editing.summary" rows="2"/></label><label class="span-2">รายละเอียด<textarea v-model="editing.body" rows="6"/></label><label class="span-2">URL รูปภาพ<input v-model="editing.image" placeholder="https://... หรืออัปโหลดภาพ"></label><div class="span-2"><label class="upload-button"><Upload :size="17"/> อัปโหลด JPEG, PNG หรือ WebP (ไม่เกิน 5 MB)<input type="file" accept="image/jpeg,image/png,image/webp" hidden @change="upload"></label><img v-if="editing.image" class="image-preview" :src="editing.image" alt="ภาพตัวอย่าง"></div></div><button class="btn btn-yellow" :disabled="busy"><Save :size="17"/> บันทึก</button></form>
<form v-else-if="tab==='settings'" class="admin-form" @submit.prevent="saveSettings"><h2>ข้อมูลบริษัทและเว็บไซต์</h2><div class="form-grid"><label v-for="(label,key) in settingLabels" :key="key" :class="{'span-2':['address','about','privacy','terms'].includes(key)}">{{label}}<textarea v-if="['address','about','privacy','terms'].includes(key)" v-model="settings[key]" rows="3"/><input v-else v-model="settings[key]"></label></div><button class="btn btn-yellow" :disabled="busy"><Save :size="17"/> บันทึกข้อมูล</button></form>
<div v-else-if="tab==='users'"><div class="table-wrap"><table><thead><tr><th>ผู้ใช้</th><th>สิทธิ์</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}</td><td>{{u.role}}</td></tr></tbody></table></div><form class="admin-form" @submit.prevent="addUser"><h2>เพิ่มผู้ใช้งาน</h2><div class="form-grid"><label>ชื่อผู้ใช้<input v-model="newUser.username" required pattern="[a-zA-Z0-9._-]{3,100}"></label><label>รหัสผ่าน (อย่างน้อย 12 ตัวอักษร)<input v-model="newUser.password" type="password" required minlength="12" maxlength="72"></label><label>สิทธิ์<select v-model="newUser.role"><option value="editor">ผู้ดูแลเนื้อหา</option><option value="admin">ผู้ดูแลระบบ</option></select></label></div><button class="btn btn-yellow"><Plus :size="17"/> เพิ่มผู้ใช้</button></form></div></main></div></div></template>
